package com.procurement.rfq.service;import com.procurement.common.exception.*;import com.procurement.common.response.*;import com.procurement.rfq.dto.request.*;import com.procurement.rfq.dto.response.*;import com.procurement.rfq.entity.*;import com.procurement.rfq.exception.*;import com.procurement.rfq.mapper.*;import com.procurement.rfq.repository.*;import com.procurement.vendor.entity.Vendor;import com.procurement.vendor.repository.VendorRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class RfqVendorServiceImpl implements RfqVendorService{private final RfqVendorRepository repo;private final RfqRepository rfqs;private final VendorRepository vendors;private final RfqMapper mapper;public RfqVendorServiceImpl(RfqVendorRepository r,RfqRepository f,VendorRepository v,RfqMapper m){repo=r;rfqs=f;vendors=v;mapper=m;}private Rfq rfq(Long id){return rfqs.findById(id).orElseThrow(()->new RfqNotFoundException(id));}@Transactional public RfqVendorResponse invite(Long id,RfqVendorRequest r){var rfq=rfq(id);if(rfq.getStatus()==RfqStatus.CLOSED||rfq.getStatus()==RfqStatus.CANCELLED)throw new ConflictException("Vendors cannot be invited to this RFQ");if(repo.existsByRfqIdAndVendorId(id,r.vendorId()))throw new ConflictException("Vendor already invited");var v=vendors.findById(r.vendorId()).orElseThrow(()->new ResourceNotFoundException("Vendor not found: "+r.vendorId()));if(!"ACTIVE".equalsIgnoreCase(v.getStatus())||!Boolean.TRUE.equals(v.getApproved()))throw new ConflictException("Vendor must be active and approved");return mapper.toVendorResponse(repo.save(RfqVendor.builder().rfq(rfq).vendor(v).remarks(r.remarks()).responseStatus(RfqVendorStatus.INVITED).build()));}@Transactional public void remove(Long id,Long vendorId){var x=repo.findByRfqIdAndVendorId(id,vendorId).orElseThrow(()->new ResourceNotFoundException("RFQ vendor invitation not found"));if(x.getResponseStatus()!=RfqVendorStatus.INVITED)throw new ConflictException("Responded invitations cannot be removed");repo.delete(x);}@Transactional(readOnly=true)public PageResponse<RfqVendorResponse>search(Long r,Long v,Pageable p){var s=(org.springframework.data.jpa.domain.Specification<RfqVendor>)((root,q,b)->{var x=b.conjunction();if(r!=null)x=b.and(x,b.equal(root.get("rfq").get("id"),r));if(v!=null)x=b.and(x,b.equal(root.get("vendor").get("id"),v));return x;});Page<RfqVendorResponse>z=repo.findAll(s,p).map(mapper::toVendorResponse);return new PageResponse<>(z.getContent(),z.getNumber(),z.getSize(),z.getTotalElements(),z.getTotalPages(),z.isLast());}}
